BEGIN;
CREATE TABLE IF NOT EXISTS seymour_engine.integration_clients (integration_client_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_key TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, api_version TEXT NOT NULL DEFAULT 'v1', enabled BOOLEAN NOT NULL DEFAULT TRUE, capabilities JSONB NOT NULL DEFAULT '[]'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seymour_engine.integration_commands (command_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), client_key TEXT NOT NULL, idempotency_key TEXT NOT NULL, correlation_id TEXT NOT NULL, capability TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, parameters JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'accepted', result JSONB, error_message TEXT, requested_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, UNIQUE(client_key,idempotency_key));
CREATE INDEX IF NOT EXISTS ix_integration_commands_correlation ON seymour_engine.integration_commands(correlation_id);
CREATE TABLE IF NOT EXISTS seymour_engine.integration_events (integration_event_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), event_type TEXT NOT NULL, correlation_id TEXT, payload JSONB NOT NULL DEFAULT '{}'::jsonb, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seymour_engine.compatibility_matrix (compatibility_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), consumer TEXT NOT NULL, consumer_version TEXT NOT NULL, engine_api_version TEXT NOT NULL, status TEXT NOT NULL, notes TEXT, UNIQUE(consumer,consumer_version,engine_api_version));
CREATE TABLE IF NOT EXISTS seymour_engine.release_validations (release_validation_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), validation_key TEXT NOT NULL, status TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, checked_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS seymour_engine.release_checklists (release_checklist_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), release_version TEXT NOT NULL, item_key TEXT NOT NULL, display_name TEXT NOT NULL, required BOOLEAN NOT NULL DEFAULT TRUE, status TEXT NOT NULL DEFAULT 'pending', notes TEXT, UNIQUE(release_version,item_key));
INSERT INTO seymour_engine.integration_clients(client_key,display_name,api_version,capabilities) VALUES ('nexus-command-center','Nexus Command Center','v1','["summary.read","readiness.read","command.submit"]'::jsonb) ON CONFLICT(client_key) DO NOTHING;
INSERT INTO seymour_engine.compatibility_matrix(consumer,consumer_version,engine_api_version,status,notes) VALUES ('nexus-command-center','1.x','v1','supported','Initial Version 1.0 integration contract') ON CONFLICT DO NOTHING;
INSERT INTO seymour_engine.release_checklists(release_version,item_key,display_name,status) VALUES ('1.0.0','database','Database migrations applied','complete'),('1.0.0','security','Security foundation configured','complete'),('1.0.0','backup','Backup foundation configured','complete'),('1.0.0','integration','Nexus integration verified','pending') ON CONFLICT DO NOTHING;
INSERT INTO seymour_engine.schema_migrations(migration_id) VALUES ('019_nexus_integration_release_readiness') ON CONFLICT DO NOTHING;
COMMIT;
